#!/usr/bin/env bash
set -euo pipefail

SELF="$(basename "$0")"
COMMIT_MSG="CARLOS FINAL: coaching intelligence, data integrity and mobile PWA"

echo "[CARLOS FINAL] Preflight..."
if [[ ! -f package.json || ! -d src || ! -d public ]]; then
  echo "ERROR: uruchom skrypt w katalogu głównym repozytorium CARLOS."
  exit 1
fi
if ! git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  echo "ERROR: to nie jest repozytorium Git."
  exit 1
fi
if ! git diff --quiet || ! git diff --cached --quiet; then
  echo "ERROR: są niezapisane śledzone zmiany. Najpierw je zachowaj albo wycofaj."
  git status --short
  exit 1
fi

write_b64() {
  local path="$1"
  local payload="$2"
  mkdir -p "$(dirname "$path")"
  printf '%s' "$payload" | base64 -d > "$path"
}

echo "[CARLOS FINAL] Zapis plików..."
write_b64 'package.json' ''
write_b64 'index.html' ''
write_b64 'public/manifest.webmanifest' ''
write_b64 'public/sw.js' ''
write_b64 'src/main.jsx' ''
write_b64 'src/styles.css' ''
write_b64 'src/parse.js' ''
write_b64 'src/parse.test.js' ''
write_b64 'src/performance.js' ''
write_b64 'src/performance.test.js' ''
write_b64 'vite.config.js' 'aW1wb3J0IHsgZGVmaW5lQ29uZmlnIH0gZnJvbSAndml0ZSc7CmltcG9ydCByZWFjdCBmcm9tICdAdml0ZWpzL3BsdWdpbi1yZWFjdCc7CgpleHBvcnQgZGVmYXVsdCBkZWZpbmVDb25maWcoewogIHBsdWdpbnM6IFtyZWFjdCgpXSwKICBzZXJ2ZXI6IHsgaG9zdDogdHJ1ZSB9LAp9KTsK'


echo "[CARLOS FINAL] Testy..."
npm test

echo "[CARLOS FINAL] Build produkcyjny..."
npm run build

rm -rf dist
rm -f -- "$SELF"

echo "[CARLOS FINAL] Kontrola diff..."
git diff --check

git add package.json index.html public/manifest.webmanifest public/sw.js \
  src/main.jsx src/styles.css src/parse.js src/parse.test.js \
  src/performance.js src/performance.test.js vite.config.js
# Skrypt został wcześniej dodany do repo podczas uploadu; jego usunięcie ma wejść do finalnego commita.
git add -u -- "$SELF" 2>/dev/null || true

if git diff --cached --quiet; then
  echo "[CARLOS FINAL] Brak zmian do commita."
  exit 0
fi

echo "[CARLOS FINAL] Commit..."
git commit -m "$COMMIT_MSG"

echo "[CARLOS FINAL] Push main..."
git push origin main

echo
echo "=============================================="
echo " CARLOS FINAL WDROŻONY"
echo "=============================================="
git --no-pager log -1 --oneline
echo "Tests: PASS"
echo "Build: PASS"
echo "Push: origin/main"
echo "Vercel: powinien rozpocząć automatyczny deployment"
echo "=============================================="
